  1→import fs from 'fs';
  2→import path from 'path';
  3→import { execSync } from 'child_process';
  4→
  5→/**
  6→ * Extract YAML frontmatter from a skill file.
  7→ * Current format:
  8→ * ---
  9→ * name: skill-name
 10→ * description: Use when [condition] - [what it does]
 11→ * ---
 12→ *
 13→ * @param {string} filePath - Path to SKILL.md file
 14→ * @returns {{name: string, description: string}}
 15→ */
 16→function extractFrontmatter(filePath) {
 17→    try {
 18→        const content = fs.readFileSync(filePath, 'utf8');
 19→        const lines = content.split('\n');
 20→
 21→        let inFrontmatter = false;
 22→        let name = '';
 23→        let description = '';
 24→
 25→        for (const line of lines) {
 26→            if (line.trim() === '---') {
 27→                if (inFrontmatter) break;
 28→                inFrontmatter = true;
 29→                continue;
 30→            }
 31→
 32→            if (inFrontmatter) {
 33→                const match = line.match(/^(\w+):\s*(.*)$/);
 34→                if (match) {
 35→                    const [, key, value] = match;
 36→                    switch (key) {
 37→                        case 'name':
 38→                            name = value.trim();
 39→                            break;
 40→                        case 'description':
 41→                            description = value.trim();
 42→                            break;
 43→                    }
 44→                }
 45→            }
 46→        }
 47→
 48→        return { name, description };
 49→    } catch (error) {
 50→        return { name: '', description: '' };
 51→    }
 52→}
 53→
 54→/**
 55→ * Find all SKILL.md files in a directory recursively.
 56→ *
 57→ * @param {string} dir - Directory to search
 58→ * @param {string} sourceType - 'personal' or 'superpowers' for namespacing
 59→ * @param {number} maxDepth - Maximum recursion depth (default: 3)
 60→ * @returns {Array<{path: string, name: string, description: string, sourceType: string}>}
 61→ */
 62→function findSkillsInDir(dir, sourceType, maxDepth = 3) {
 63→    const skills = [];
 64→
 65→    if (!fs.existsSync(dir)) return skills;
 66→
 67→    function recurse(currentDir, depth) {
 68→        if (depth > maxDepth) return;
 69→
 70→        const entries = fs.readdirSync(currentDir, { withFileTypes: true });
 71→
 72→        for (const entry of entries) {
 73→            const fullPath = path.join(currentDir, entry.name);
 74→
 75→            if (entry.isDirectory()) {
 76→                // Check for SKILL.md in this directory
 77→                const skillFile = path.join(fullPath, 'SKILL.md');
 78→                if (fs.existsSync(skillFile)) {
 79→                    const { name, description } = extractFrontmatter(skillFile);
 80→                    skills.push({
 81→                        path: fullPath,
 82→                        skillFile: skillFile,
 83→                        name: name || entry.name,
 84→                        description: description || '',
 85→                        sourceType: sourceType
 86→                    });
 87→                }
 88→
 89→                // Recurse into subdirectories
 90→                recurse(fullPath, depth + 1);
 91→            }
 92→        }
 93→    }
 94→
 95→    recurse(dir, 0);
 96→    return skills;
 97→}
