 99→/**
100→ * Resolve a skill name to its file path, handling shadowing
101→ * (personal skills override superpowers skills).
102→ *
103→ * @param {string} skillName - Name like "superpowers:brainstorming" or "my-skill"
104→ * @param {string} superpowersDir - Path to superpowers skills directory
105→ * @param {string} personalDir - Path to personal skills directory
106→ * @returns {{skillFile: string, sourceType: string, skillPath: string} | null}
107→ */
108→function resolveSkillPath(skillName, superpowersDir, personalDir) {
109→    // Strip superpowers: prefix if present
110→    const forceSuperpowers = skillName.startsWith('superpowers:');
111→    const actualSkillName = forceSuperpowers ? skillName.replace(/^superpowers:/, '') : skillName;
112→
113→    // Try personal skills first (unless explicitly superpowers:)
114→    if (!forceSuperpowers && personalDir) {
115→        const personalPath = path.join(personalDir, actualSkillName);
116→        const personalSkillFile = path.join(personalPath, 'SKILL.md');
117→        if (fs.existsSync(personalSkillFile)) {
118→            return {
119→                skillFile: personalSkillFile,
120→                sourceType: 'personal',
121→                skillPath: actualSkillName
122→            };
123→        }
124→    }
125→
126→    // Try superpowers skills
127→    if (superpowersDir) {
128→        const superpowersPath = path.join(superpowersDir, actualSkillName);
129→        const superpowersSkillFile = path.join(superpowersPath, 'SKILL.md');
130→        if (fs.existsSync(superpowersSkillFile)) {
131→            return {
132→                skillFile: superpowersSkillFile,
133→                sourceType: 'superpowers',
134→                skillPath: actualSkillName
135→            };
136→        }
137→    }
138→
139→    return null;
140→}
