142→/**
143→ * Check if a git repository has updates available.
144→ *
145→ * @param {string} repoDir - Path to git repository
146→ * @returns {boolean} - True if updates are available
147→ */
148→function checkForUpdates(repoDir) {
149→    try {
150→        // Quick check with 3 second timeout to avoid delays if network is down
151→        const output = execSync('git fetch origin && git status --porcelain=v1 --branch', {
152→            cwd: repoDir,
153→            timeout: 3000,
154→            encoding: 'utf8',
155→            stdio: 'pipe'
156→        });
157→
158→        // Parse git status output to see if we're behind
159→        const statusLines = output.split('\n');
160→        for (const line of statusLines) {
161→            if (line.startsWith('## ') && line.includes('[behind ')) {
162→                return true; // We're behind remote
163→            }
164→        }
165→        return false; // Up to date
166→    } catch (error) {
167→        // Network down, git error, timeout, etc. - don't block bootstrap
168→        return false;
169→    }
170→}
