172→/**
173→ * Strip YAML frontmatter from skill content, returning just the content.
174→ *
175→ * @param {string} content - Full content including frontmatter
176→ * @returns {string} - Content without frontmatter
177→ */
178→function stripFrontmatter(content) {
179→    const lines = content.split('\n');
180→    let inFrontmatter = false;
181→    let frontmatterEnded = false;
182→    const contentLines = [];
183→
184→    for (const line of lines) {
185→        if (line.trim() === '---') {
186→            if (inFrontmatter) {
187→                frontmatterEnded = true;
188→                continue;
189→            }
190→            inFrontmatter = true;
191→            continue;
192→        }
193→
194→        if (frontmatterEnded || !inFrontmatter) {
195→            contentLines.push(line);
196→        }
197→    }
198→
199→    return contentLines.join('\n').trim();
200→}
